// Meta webhook verification handshake.
// Meta calls this once when you register the callback URL in the app dashboard.
const q = $input.first().json.query || {};
const verifyToken = $env.META_WEBHOOK_VERIFY_TOKEN;
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === verifyToken) {
  return [{ json: { status: 200, body: q['hub.challenge'] } }];
}
return [{ json: { status: 403, body: 'verification failed' } }];

// Reject anything that is not a verified relay from Nexa -- Meta's webhook is
// registered on Nexa's shared Meta app now, not this URL directly (see
// docs/setup.md, 'Shared Meta app with Nexa'). Silently drop rather than
// respond 401: this node's webhook responseMode is 'onReceived', so n8n
// already sent 200 by the time this code runs -- there is no HTTP response
// left to change, only whether we act on the payload.
const headers = $input.first().json.headers || {};
if (headers['x-bali-forward-secret'] !== $env.BALI_FORWARD_SECRET) {
  return [{ json: { skip: true } }];
}

// Parse the Meta WhatsApp Cloud API webhook payload down to the fields we care about.
// Meta's payload shape: entry[0].changes[0].value.messages[0]
const body = $input.first().json.body;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

if (!message) {
  // status callbacks (delivered/read) or other non-message events - nothing to route
  return [{ json: { skip: true } }];
}

const fromNumber = message.from; // E.164 without '+'
const text = message.text?.body || null;
const mediaId = message.image?.id || message.document?.id || message.audio?.id || null;
const mediaType = message.image ? 'image' : message.document ? 'document' : message.audio ? 'audio' : null;
const contextMessageId = message.context?.id || null; // set when the sender replied-to a specific message

// Owner's explicit call (2026-08-03): one universal "type okay to receive
// update" mechanism, here in the ONE place every inbound message passes
// through regardless of role -- not per-role logic duplicated in
// stage1-code.js/pm-toggle-code.js/stage3-4-action-code.js (removed). This
// means it works identically for roles that have no other reply-handling
// at all today (HR, security, procurement, accounts, event_assistant,
// supervisor, facility_manager, general staff), not just customer/PM/
// lawyer. Real content that couldn't be delivered (outside the 24h window)
// sits in queued_messages (see schema.sql) until the sender's own next
// message affirms with any of ok/okay/yh/yeah/yes -- same affirmative
// vocabulary already used elsewhere in this codebase (e.g. contract/invoice
// approval checks), not just the literal word "okay".
const helpers = this.helpers;
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_KEY = $env.SUPABASE_SERVICE_KEY;
const META_TOKEN = $env.META_ACCESS_TOKEN;
const META_PHONE_ID = $env.META_PHONE_NUMBER_ID;
const sbHeaders = { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json' };

const isAffirmative = text && /^(y(es)?|yeah|yh|yep|yup|sure|ok(ay)?)\b/i.test(text.trim());

if (isAffirmative) {
  const queued = await helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/queued_messages?phone_number=eq.${encodeURIComponent(fromNumber)}&order=created_at.asc&select=*`,
    headers: sbHeaders,
    json: true,
    timeout: 15000,
  });
  if (Array.isArray(queued) && queued.length > 0) {
    for (const row of queued) {
      if (META_TOKEN) {
        try {
          await helpers.httpRequest({
            method: 'POST',
            url: `https://graph.facebook.com/v20.0/${META_PHONE_ID}/messages`,
            headers: { Authorization: `Bearer ${META_TOKEN}`, 'Content-Type': 'application/json' },
            body: { messaging_product: 'whatsapp', to: fromNumber, type: 'text', text: { body: row.message_text } },
            json: true,
            timeout: 20000,
          });
        } catch (e) {
          // Best-effort -- if this particular send fails, still clear the
          // row (matches every other flush-on-reply implementation this
          // session) rather than risk resending it forever on every future
          // affirmative reply.
        }
      } else {
        // Sandbox: no real Meta token configured -- log the same way every
        // other sandboxLog() in this codebase does, so the sandbox test
        // webpage displays it.
        try {
          await helpers.httpRequest({
            method: 'POST',
            url: `${SUPABASE_URL}/rest/v1/sandbox_outbound`,
            headers: sbHeaders,
            body: {
              to_number: fromNumber,
              kind: 'text',
              message_text: row.message_text,
              message_id: `sandbox-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            },
            json: true,
            timeout: 15000,
          });
        } catch (e) {}
      }
      try {
        await helpers.httpRequest({
          method: 'DELETE',
          url: `${SUPABASE_URL}/rest/v1/queued_messages?id=eq.${row.id}`,
          headers: sbHeaders,
          json: true,
          timeout: 15000,
        });
      } catch (e) {}
    }
    // Deliberately does NOT stop here (no early return) -- this same "yes"/
    // "okay" might ALSO be a genuine answer to something else entirely
    // (e.g. "have you hosted an event before?"), not purely an unlock
    // keyword. Flushing is a side effect; the message still continues to
    // normal role-based routing below so a real answer is never silently
    // swallowed just because something happened to be queued at the same
    // moment.
  }
}

return [{
  json: {
    skip: false,
    from_number: fromNumber,
    text,
    media_id: mediaId,
    media_type: mediaType,
    reply_to_message_id: contextMessageId,
    whatsapp_message_id: message.id,
    received_at: message.timestamp
  }
}];

// Section 9a: unrecognized number falls back to 'customer' and the sales flow.
// Lookup Contact (an HTTP Request node) already returns one item per matched
// row -- NOT a wrapped array -- or a bare {} via alwaysOutputData when there
// is no match. Checking Array.isArray() here was always wrong: it made this
// return 'customer' for EVERY sender regardless of their real role, since
// launch (confirmed live -- a real PM contact was never once routed as pm).
const inbound = $('Parse Inbound Message').first().json;
const contactItem = $input.first().json;
const contact = contactItem && contactItem.id ? contactItem : null;

const role = contact ? contact.role : 'customer';

return [{
  json: {
    ...inbound,
    contact_id: contact ? contact.id : null,
    role
  }
}];

// Other staff roles (HR, procurement, security, etc.): no inbound flow yet --
// they're only ever messaged (Stage 5 fan-out), not expected to message the bot back.
console.log('Unrouted role, logging only:', $input.first().json.role);
return $input.all();
